#[test]
fn unit_metadata() {
    let info = MolarMass::<f64>::INFO;
    assert_eq!(info.name, "MolarMass");
    assert_eq!(info.units.len(), MolarMassUnit::ALL.len());
    for (&unit, unit_info) in MolarMassUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, MolarMassUnit::KilogramPerMole.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::GramPerMole),
        MolarMass::from_grams_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::GramPerMole),
        MolarMass::from_base(v).as_grams_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::NanogramPerMole),
        MolarMass::from_nanograms_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::NanogramPerMole),
        MolarMass::from_base(v).as_nanograms_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::MicrogramPerMole),
        MolarMass::from_micrograms_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::MicrogramPerMole),
        MolarMass::from_base(v).as_micrograms_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::MilligramPerMole),
        MolarMass::from_milligrams_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::MilligramPerMole),
        MolarMass::from_base(v).as_milligrams_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::CentigramPerMole),
        MolarMass::from_centigrams_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::CentigramPerMole),
        MolarMass::from_base(v).as_centigrams_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::DecigramPerMole),
        MolarMass::from_decigrams_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::DecigramPerMole),
        MolarMass::from_base(v).as_decigrams_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::DecagramPerMole),
        MolarMass::from_decagrams_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::DecagramPerMole),
        MolarMass::from_base(v).as_decagrams_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::HectogramPerMole),
        MolarMass::from_hectograms_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::HectogramPerMole),
        MolarMass::from_base(v).as_hectograms_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::KilogramPerMole),
        MolarMass::from_kilograms_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::KilogramPerMole),
        MolarMass::from_base(v).as_kilograms_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::KilogramPerKilomole),
        MolarMass::from_kilograms_per_kilomole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::KilogramPerKilomole),
        MolarMass::from_base(v).as_kilograms_per_kilomole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::PoundPerMole),
        MolarMass::from_pounds_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::PoundPerMole),
        MolarMass::from_base(v).as_pounds_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::KilopoundPerMole),
        MolarMass::from_kilopounds_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::KilopoundPerMole),
        MolarMass::from_base(v).as_kilopounds_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::MegapoundPerMole),
        MolarMass::from_megapounds_per_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::MegapoundPerMole),
        MolarMass::from_base(v).as_megapounds_per_mole()
    );
    assert_eq!(
        MolarMass::new(v, MolarMassUnit::PoundPerPoundMole),
        MolarMass::from_pounds_per_pound_mole(v)
    );
    assert_eq!(
        MolarMass::from_base(v).convert_to(MolarMassUnit::PoundPerPoundMole),
        MolarMass::from_base(v).as_pounds_per_pound_mole()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [MolarMass; 14] = [
        MolarMass::const_new(1234.5, MolarMassUnit::GramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::NanogramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::MicrogramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::MilligramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::CentigramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::DecigramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::DecagramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::HectogramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::KilogramPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::KilogramPerKilomole),
        MolarMass::const_new(1234.5, MolarMassUnit::PoundPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::KilopoundPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::MegapoundPerMole),
        MolarMass::const_new(1234.5, MolarMassUnit::PoundPerPoundMole),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(MolarMassUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            MolarMass::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in MolarMassUnit::ALL {
            assert_eq!(
                MolarMass::const_new(v, unit).as_base().to_bits(),
                MolarMass::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = MolarMass::from_base(v);
        let auto = q.auto_unit();
        assert_close(MolarMass::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in MolarMassUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        MolarMass::from_base(0.0).auto_unit().unit,
        MolarMassUnit::KilogramPerMole
    );
}

